ALIAS(
  DOWNSAMPLE(
    DIVIDE(
      SUM(
        CULL_BELOW(
          RATE(
            $start:$end:core.$substrate.$fi.$fd:SFDC_type-ServerMetrics.LogMetric-WALL_TIME{role=app,cell=$cell,k8s_pod_name=*}:none:1m-max
          ),
          #0#,#value#
        ),
        #union#
      ),
      CULL_BELOW(
        SUM(
          CULL_BELOW(
            RATE(
              $start:$end:core.$substrate.$fi.$fd:SFDC_type-ServerMetrics.LogMetric-COUNT{role=app,cell=$cell,k8s_pod_name=*}:none:1m-max
            ),
            #0#,#value#
          ),
          #union#
        ),
        #1#,#value#
      ),
      #union#,#0#
    ),
    #$interval-$agg#
  ),
  #wall_time#,#literal#
)

